DROP TABLE IF EXISTS `producto`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `producto` (
  `id_producto` int NOT NULL AUTO_INCREMENT,
  `id_vendedor` int NOT NULL,
  `titulo` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `precio` decimal(15,2) NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `categoria` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `marca` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Zara, Levi''s, vintage sin marca',
  `talla` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'XS, S, M, L, 36, 38',
  `color` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Negro, azul, estampado',
  `material` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Algodón, cuero, lana',
  `decada` enum('50s','60s','70s','80s','90s','2000s','desconocida') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'desconocida' COMMENT 'Década de la prenda',
  `tipo_prenda` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Vestido, blazer, bolso, calzado',
  `condicion` enum('excelente','muy_bueno','bueno','regular') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bueno' COMMENT 'Estado real de la prenda',
  `autenticidad` enum('original','inspiracion','sin_etiqueta') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sin_etiqueta' COMMENT 'Original, inspiración o sin etiqueta',
  `medidas` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Busto 90cm, cintura 70cm',
  `imagen_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado_producto` enum('nuevo','usado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'nuevo',
  `visibilidad` enum('activo','oculto','eliminado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'activo',
  `politica_devolucion` text COLLATE utf8mb4_unicode_ci COMMENT 'CA018',
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_producto`),
  KEY `id_vendedor` (`id_vendedor`),
  KEY `idx_producto_marca` (`marca`),
  KEY `idx_producto_talla` (`talla`),
  KEY `idx_producto_decada` (`decada`),
  KEY `idx_producto_tipo_prenda` (`tipo_prenda`),
  KEY `idx_producto_condicion` (`condicion`),
  CONSTRAINT `producto_ibfk_1` FOREIGN KEY (`id_vendedor`) REFERENCES `vendedor` (`id_vendedor`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

