INSERT INTO `producto` (`id_vendedor`,`titulo`,`descripcion`,`precio`,`stock`,`categoria`,`marca`,`talla`,`color`,`material`,`decada`,`tipo_prenda`,`condicion`,`autenticidad`,`medidas`,`estado_producto`,`visibilidad`,`politica_devolucion`,`fecha_creacion`) VALUES
(1,'Vestido de tweed Chanel Boutique','Vestido recto de tweed de lana con ribete trenzado y botones dorados con el logo. Forro de seda completo. Etiqueta Chanel Boutique cosida y número de serie legible. Sin manchas ni arreglos.',4200000.00,1,'Ropa','Chanel Boutique','38','Beige y negro','Tweed de lana','80s','Vestido','excelente','original','Busto 90 cm · Cintura 72 cm · Largo 105 cm','usado','activo','Pieza de archivo de venta final. Se acepta reclamo únicamente si la autenticidad o el estado no corresponden a lo publicado; el comprador debe avisar en las primeras 48 horas con fotos del hallazgo.',DATE_SUB(NOW(), INTERVAL 99 DAY)),
(1,'Blazer Christian Dior Boutique','Blazer entallado de lana fría con botonadura doble y hombreras suaves. Forro con monograma Dior intacto. Pequeño desgaste en el borde de un puño, imperceptible al usarlo.',1650000.00,1,'Ropa','Christian Dior','38','Azul marino','Lana','80s','Blazer','muy_bueno','original','Busto 90 cm · Cintura 72 cm · Largo 62 cm','usado','activo','Pieza de archivo de venta final. Se acepta reclamo únicamente si la autenticidad o el estado no corresponden a lo publicado; el comprador debe avisar en las primeras 48 horas con fotos del hallazgo.',DATE_SUB(NOW(), INTERVAL 98 DAY)),
(1,'Chaqueta Yves Saint Laurent Rive Gauche','Chaqueta de corte sastre en lana negra con solapa ancha. Etiqueta Rive Gauche original y forro de acetato en buen estado. Pieza de archivo con la silueta de los años 70.',2100000.00,1,'Ropa','Yves Saint Laurent','36','Negro','Lana','70s','Chaqueta','muy_bueno','original','Busto 86 cm · Cintura 68 cm · Largo 58 cm','usado','activo','Pieza de archivo de venta final. Se acepta reclamo únicamente si la autenticidad o el estado no corresponden a lo publicado; el comprador debe avisar en las primeras 48 horas con fotos del hallazgo.',DATE_SUB(NOW(), INTERVAL 97 DAY)),
(1,'Carré de seda Hermès 90 cm','Carré de seda con dobladillo enrollado a mano y etiqueta Hermès Paris. Colores vivos, sin manchas ni hilos sueltos. Se entrega en bolsa de tela.',1900000.00,1,'Ropa','Hermès','Única','Multicolor','Seda','90s','Accesorio','excelente','original','90 x 90 cm','usado','activo','Pieza de archivo de venta final. Se acepta reclamo únicamente si la autenticidad o el estado no corresponden a lo publicado; el comprador debe avisar en las primeras 48 horas con fotos del hallazgo.',DATE_SUB(NOW(), INTERVAL 96 DAY)),
(1,'Bolso Louis Vuitton Speedy 30 monograma','Speedy 30 en lona monograma con asas de cuero natural que ya tomaron la pátina color miel. Cremallera y herrajes funcionan bien; esquinas con desgaste leve. Código de fecha visible en el interior.',3800000.00,1,'Ropa','Louis Vuitton','Única','Marrón','Lona monograma y cuero','90s','Bolso','bueno','original','Ancho 30 cm · Alto 21 cm · Fondo 17 cm','usado','activo','Pieza de archivo de venta final. Se acepta reclamo únicamente si la autenticidad o el estado no corresponden a lo publicado; el comprador debe avisar en las primeras 48 horas con fotos del hallazgo.',DATE_SUB(NOW(), INTERVAL 95 DAY)),
(1,'Bolso Gucci Bamboo de mano','Bolso de mano con asa de bambú tostado y cuero negro de textura suave. Forro de gamuza intacto y cierre firme. Ligeras marcas de uso en la base.',3200000.00,1,'Ropa','Gucci','Única','Negro','Cuero','90s','Bolso','muy_bueno','original','Ancho 24 cm · Alto 18 cm · Fondo 9 cm','usado','activo','Pieza de archivo de venta final. Se acepta reclamo únicamente si la autenticidad o el estado no corresponden a lo publicado; el comprador debe avisar en las primeras 48 horas con fotos del hallazgo.',DATE_SUB(NOW(), INTERVAL 94 DAY)),
(1,'Trench Burberry clásico de gabardina','Trench de gabardina de algodón con forro desmontable a cuadros Burberry, cinturón y charreteras originales. Botones de cuerno completos. Cuello sin desgaste.',1450000.00,1,'Ropa','Burberry','38','Beige','Gabardina de algodón','80s','Abrigo','muy_bueno','original','Busto 90 cm · Cintura 72 cm · Largo 105 cm','usado','activo','Pieza de archivo de venta final. Se acepta reclamo únicamente si la autenticidad o el estado no corresponden a lo publicado; el comprador debe avisar en las primeras 48 horas con fotos del hallazgo.',DATE_SUB(NOW(), INTERVAL 93 DAY)),
